<script setup lang="ts">
import { computed,reactive,ref } from "vue"; import {useRouter} from "vue-router"; import {Plus} from "lucide-vue-next";
import AppShell from "@/components/zs/AppShell.vue"; import PageHeader from "@/components/zs/PageHeader.vue"; import Panel from "@/components/zs/Panel.vue"; import DataTable,{type Column} from "@/components/zs/DataTable.vue"; import Toolbar from "@/components/zs/Toolbar.vue"; import SearchInput from "@/components/zs/SearchInput.vue"; import StatusBadge from "@/components/zs/StatusBadge.vue"; import StatCard from "@/components/zs/StatCard.vue"; import ZButton from "@/components/zs/ZButton.vue"; import SidePanel from "@/components/zs/SidePanel.vue"; import Field from "@/components/zs/Field.vue"; import AsyncSection from "@/components/zs/AsyncSection.vue"; import ValidationMessage from "@/components/zs/ValidationMessage.vue"; import Pagination from "@/components/crm/Pagination.vue";
import {useCrmData} from "@/composables/useCrmData"; import {useAsyncData,useMutation} from "@/composables/useAsyncData"; import {crmRepository} from "@/services/crm/repository"; import type {CrmDeal} from "@/types/crm"; import {formatMoney,formatMoneyCompact,parseMoneyInput,toMoneyInput} from "@/lib/money"; import {showToast} from "@/composables/useToast"; import {setPageMeta} from "@/lib/page-meta";
setPageMeta("Deals","Qualified opportunities, ownership, value and expected close dates.");const data=useCrmData(),router=useRouter(),search=ref(""),status=ref("All statuses"),pipelineId=ref(""),page=ref(1),open=ref(false),editingId=ref<string|null>(null);const listing=useAsyncData(()=>crmRepository.dealsPage(data.activeCompanyId.value,{search:search.value,status:status.value==="All statuses"?undefined:status.value,pipeline_id:pipelineId.value||undefined,page:page.value,per_page:10}),{watch:[data.activeCompanyId,search,status,pipelineId,page]});const rows=computed(()=>listing.data.value?.data??[]);const dashboard=computed(()=>data.dashboard.data.value);const form=reactive({title:"",account_id:"",primary_contact_id:"",pipeline_id:"",pipeline_stage_id:"",owner_id:"",amount:"0.00",currency:"PKR",expected_close_date:"",source:"",description:"",loss_reason:""});const columns:Column[]=[{key:"name",header:"Deal"},{key:"company",header:"Company"},{key:"stage",header:"Stage"},{key:"value",header:"Value",align:"right"},{key:"probability",header:"Probability",align:"right"},{key:"expectedClose",header:"Expected close"},{key:"owner",header:"Owner"},{key:"status",header:"Status"},{key:"actions",header:"",align:"right"}];const stages=computed(()=>data.pipelines.data.value?.find((item)=>item.id===form.pipeline_id)?.stages??[]);const contacts=computed(()=>(data.contacts.data.value??[]).filter((item)=>item.accountId===form.account_id));
function edit(item?:CrmDeal){const pipeline=item?data.pipelines.data.value?.find((entry)=>entry.id===item.pipelineId):(data.pipelines.data.value?.find((entry)=>entry.isDefault)??data.pipelines.data.value?.[0]);editingId.value=item?.id??null;Object.assign(form,{title:item?.name??"",account_id:item?.accountId??"",primary_contact_id:item?.primaryContactId??"",pipeline_id:pipeline?.id??"",pipeline_stage_id:item?.pipelineStageId??pipeline?.stages[0]?.id??"",owner_id:item?.ownerId?String(item.ownerId):"",amount:toMoneyInput(item?.value??0),currency:item?.currency??"PKR",expected_close_date:item?.expectedClose??"",source:item?.source??"",description:item?.description??"",loss_reason:item?.lossReason??""});open.value=true;}
const mutation=useMutation(()=>{const amount=parseMoneyInput(form.amount);const input={...form,amount:amount??-1,primary_contact_id:form.primary_contact_id||null,owner_id:form.owner_id?Number(form.owner_id):null,expected_close_date:form.expected_close_date||null,loss_reason:form.loss_reason||null};return editingId.value?crmRepository.updateDeal(data.activeCompanyId.value,editingId.value,input):crmRepository.createDeal(data.activeCompanyId.value,input)});async function save(){const saved=await mutation.run();if(!saved)return;open.value=false;await Promise.all([listing.refresh(),data.deals.refresh(),data.dashboard.refresh()]);showToast("Deal saved",`${saved.name} is up to date.`,"success");}
</script>
<template><AppShell><PageHeader title="Deals" :description="`${listing.data.value?.total??0} opportunities in the active company`"><template #actions><ZButton @click="edit()"><Plus class="size-4"/>Add deal</ZButton><ZButton variant="outline" @click="router.push('/crm/pipeline')">Pipeline board</ZButton></template></PageHeader><div class="mb-3 grid gap-3 sm:grid-cols-3"><StatCard label="Open pipeline" :value="formatMoneyCompact(dashboard?.pipelineValue??0)" tone="brand"/><StatCard label="Weighted pipeline" :value="formatMoneyCompact(dashboard?.weightedPipelineValue??0)"/><StatCard label="Won deals" :value="String(dashboard?.wonDeals??0)" tone="success"/></div><Panel><Toolbar><SearchInput v-model="search" placeholder="Search deal, company or contact"/><select v-model="status" class="field max-w-40"><option>All statuses</option><option>OPEN</option><option>WON</option><option>LOST</option></select><select v-model="pipelineId" class="field max-w-48"><option value="">All pipelines</option><option v-for="pipeline in data.pipelines.data.value??[]" :key="pipeline.id" :value="pipeline.id">{{pipeline.name}}</option></select></Toolbar><AsyncSection :loading="listing.loading.value" :error="listing.error.value" :empty="listing.data.value?.total===0" @retry="listing.refresh"><DataTable :columns="columns" :rows="rows" :min-width="1100"><template #name="{row}"><button class="font-medium text-primary hover:underline" @click="router.push(`/crm/deals/${row.id}`)">{{row.name}}</button></template><template #stage="{row}"><StatusBadge :status="row.stage"/></template><template #value="{row}"><span class="num">{{formatMoney(row.value,row.currency)}}</span></template><template #probability="{row}"><span class="num">{{row.probability}}%</span></template><template #status="{row}"><StatusBadge :status="row.status"/></template><template #actions="{row}"><ZButton variant="ghost" @click="router.push(`/crm/deals/${row.id}`)">View</ZButton><ZButton variant="ghost" :disabled="row.status!=='OPEN'" @click="edit(row)">Edit</ZButton></template><template #footer><Pagination :page="listing.data.value?.currentPage??1" :pages="listing.data.value?.lastPage??1" :total="listing.data.value?.total??0" @change="page=$event"/></template></DataTable></AsyncSection></Panel><SidePanel :open="open" :title="editingId?'Edit deal':'Add deal'" description="Values are stored in integer minor units." @close="open=false"><form class="grid gap-4 sm:grid-cols-2" @submit.prevent="save"><Field v-model="form.title" label="Deal name" required/><label><span class="label-caps">Company</span><select v-model="form.account_id" class="field mt-1.5" required><option value="">Select company</option><option v-for="company in data.companies.data.value??[]" :key="company.id" :value="company.id">{{company.name}}</option></select></label><label><span class="label-caps">Contact</span><select v-model="form.primary_contact_id" class="field mt-1.5"><option value="">No primary contact</option><option v-for="contact in contacts" :key="contact.id" :value="contact.id">{{contact.name}}</option></select></label><label><span class="label-caps">Pipeline</span><select v-model="form.pipeline_id" class="field mt-1.5" required @change="form.pipeline_stage_id=stages[0]?.id??''"><option v-for="pipeline in data.pipelines.data.value??[]" :key="pipeline.id" :value="pipeline.id">{{pipeline.name}}</option></select></label><label><span class="label-caps">Stage</span><select v-model="form.pipeline_stage_id" class="field mt-1.5" required><option v-for="stage in stages" :key="stage.id" :value="stage.id">{{stage.name}}</option></select></label><Field v-model="form.amount" label="Value (PKR)" required/><Field v-model="form.expected_close_date" label="Expected close" type="date"/><label><span class="label-caps">Owner</span><select v-model="form.owner_id" class="field mt-1.5"><option value="">Unassigned</option><option v-for="owner in data.owners.data.value??[]" :key="owner.id" :value="owner.id">{{owner.name}}</option></select></label><Field v-model="form.source" label="Source"/><label class="sm:col-span-2"><span class="label-caps">Description</span><textarea v-model="form.description" class="field mt-1.5 min-h-20"/></label><ValidationMessage class="sm:col-span-2" :message="mutation.error.value?.message"/><ZButton type="submit" :disabled="mutation.saving.value">Save deal</ZButton></form></SidePanel></AppShell></template>
